{"claim_parts": ["Receiving Party shall not reverse engineer any objects", "objects which embody Disclosing Party's Confidential Information"],
"evidence": [
{"part": 1, "relation": "entails", "same_entity": true, "same_scope": false, "quote": "(v) not to copy or reverse engineer any such Proprietary Information"},
{"part": 2, "relation": "insufficient", "same_entity": true, "same_scope": false, "quote": "which to the extent previously, presently, or subsequently disclosed to the Receiving Party is hereinafter referred to as"},
{"part": 2, "relation": "insufficient", "same_entity": false, "same_scope": false, "quote": "not to remove or export from the United States or re-export any such Proprietary Information or any direct product thereof"}
],
"missing_conditions": [
{"part": 1, "text": "The reverse engineering prohibition covers only Proprietary Information, not objects generally, and the obligations in clauses (i), (ii), (iii) and (v) do not apply after five years following disclosure.", "quote": "the foregoing clauses (i), (ii), (iii) and (v) shall not apply with respect to all obligations after five (5) years following the disclosure thereof"},
{"part": 1, "text": "The reverse engineering prohibition does not apply to information the Receiving Party can document is public, was already possessed, was rightfully received from a third party, or was independently developed.", "quote": "or any information that the Receiving Party can document"},
{"part": 1, "text": "Parties may exchange Proprietary Information under the Agreement only for a period not to exceed two years from its date, unless extended in writing or incorporated into a separate agreement.", "quote": "for a period not to exceed two (2) years from the date hereof"},
{"part": 2, "text": "Information is Proprietary Information only if first disclosed in tangible form and conspicuously marked, or if orally disclosed, identified as confidential and summarized in tangible form marked within thirty days.", "quote": "unless either (1) it is first disclosed in tangible form"}
]}

{"claim_parts": ["Agreement shall not grant Receiving Party any right to Confidential Information."],
"evidence": [{"part": 1, "relation": "contradicts", "same_entity": true, "same_scope": false, "quote": "Nothing in this agreement will restrict your ability to disclose PwC’s advice"}, {"part": 1, "relation": "contradicts", "same_entity": true, "same_scope": false, "quote": "Nothing in this agreement will prevent the receiving party from disclosing confidential information"}, {"part": 1, "relation": "insufficient", "same_entity": true, "same_scope": false, "quote": "not to use the disclosing party’s confidential information except in connection with the purpose"}],
"missing_conditions": [{"part": 1, "text": "The disclosure right in clause 2.6 is limited to PwC's advice concerning the tax (including social security) treatment or tax structure of any transaction; the claim's 'any right' omits this limit.", "quote": "concerning the tax (including social security) treatment or tax structure of any transaction"}, {"part": 1, "text": "The disclosure permission in clause 2.4 is conditional on the disclosing party's prior written consent, among other listed grounds.", "quote": "if the disclosing party has given its prior written consent"}]}

{"claim_parts": ["Receiving Party shall not solicit some of Disclosing Party's representatives."],
"evidence": [{"part": 1, "relation": "insufficient", "same_entity": true, "same_scope": false, "quote": "I will not disclose or release any information provided to me pursuant to this Agreement without proper authority or authorization"}],
"missing_conditions": []}

{"claim_parts": ["The Receiving Party shall not disclose the fact that the Agreement was agreed or negotiated."],
 "evidence": [{"part": 1, "relation": "insufficient", "same_entity": true, "same_scope": false, "quote": "In addition, Confidential Information shall include all terms and conditions of this Agreement including the fact that the parties are having discussions in order to determine the feasibility of a commercial relationship."}, {"part": 1, "relation": "insufficient", "same_entity": true, "same_scope": false, "quote": "The party receiving Confidential Information (the “Receiving Party”) shall not disclose Confidential Information to any third party without the prior written consent of the party disclosing such confidential information"}],
 "missing_conditions": [{"part": 1, "text": "The non-disclosure duty applies only absent the prior written consent of the Disclosing Party, which the claim omits.", "quote": "without the prior written consent of the party disclosing such confidential information"}]}
